from collections import deque, defaultdict

def components(g, color, conn=8):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    ds=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
    for r in range(h):
      for c in range(w):
       if g[r][c]==color and (r,c) not in seen:
        q=[(r,c)];seen.add((r,c));comp=[]
        for p in q:
         comp.append(p)
         for dr,dc in ds:
          n=(p[0]+dr,p[1]+dc)
          if 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]]==color and n not in seen:
           seen.add(n);q.append(n)
        out.append(comp)
    return out
