def shortest_path_grid(g, passable, starts, targets, conn=8, cost_fn=None):
  h,w=len(g),len(g[0]); ds=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
  dist={p:0 for p in starts}; prev={}; q=deque(starts)
  while q:
    p=q.popleft()
    if p in targets:
      path=[p]
      while p in prev:p=prev[p];path.append(p)
      return dist[path[0]],path[::-1]
    for dr,dc in ds:
      n=(p[0]+dr,p[1]+dc)
      if 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]] in passable and n not in dist:
        dist[n]=dist[p]+1;prev[n]=p;q.append(n)
  return None,None
